-- التحقق من السلامة: مجموع الأوزان يجب يكون 0.10 بالضبط
DO $$ DECLARE total NUMERIC; BEGIN
  SELECT SUM(weight_in_module) INTO total FROM indicators_catalog;
  IF ABS(total - 0.10) > 0.0001 THEN RAISE EXCEPTION 'مجموع الأوزان = % لا يساوي 0.10', total;
  ELSE RAISE NOTICE '✓ مجموع الأوزان = % (صحيح)', total; END IF;
END $$;