INSERT INTO indicators_catalog (id, name, category, category_en, tier, weight_in_module, strategy_text, ta_lib_function, sort_order) VALUES
  (1, 'Parabolic SAR', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'نقاط فوق السعر = بيع، تحت السعر = شراء. القاعدة الذهبية: لا تأخذ Flip منفردًا في الأسواق الجانبية — اشترط ADX > 25 وتوافق اتجاه H1. الأقوى استخدامه كـ Trailing Stop ديناميكي بعد دخول من إشارة مدرسة أخرى.', 'ta.SAR(high, low, 0.02, 0.2)', 1),
  (2, 'Supertrend', 'مؤشرات الاتجاه', 'Trend', 'A', 0.0018072289, 'تغير لون الخط من أحمر إلى أخضر تحت السعر = شراء، والعكس = بيع. الإعدادات: (10,3) للسكالبينج، (10,2) للأطر الأقل من 15M. لا تدخل إلا بتوافق مع تقاطع EMA20/50 + كسر هيكلي (BOS) في نفس الاتجاه.', 'df.ta.supertrend(length=10, multiplier=3.0)', 2),
  (3, 'WMA', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'السعر فوق WMA + ميل صاعد = شراء، تحت + ميل هابط = بيع. WMA(20) أسرع تجاوبًا من SMA. تقاطع WMA(9) و WMA(21) لإشارات سكالبينج، WMA(50) كـ Dynamic S/R.', 'ta.WMA(close, 20)', 3),
  (4, 'HMA', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'تغير لون HMA(21) من أحمر إلى أخضر = شراء، والعكس = بيع. الأقوى في تقليل التأخر مع المحافظة على نعومة الخط — مثالي للسكالبينج. ادخل فقط في اتجاه HMA(200) على H1 كفلتر HTF.', 'df.ta.hma(length=21)', 4),
  (5, 'VWMA', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'السعر فوق VWMA مع تباعد VWMA عن SMA لأعلى = ضغط شراء مدعوم بالحجم. تباعدها لأسفل = ضغط بيع مؤسسي. الأقوى لكشف انخراط الأموال الذكية مقارنة بالمتوسط العادي.', 'df.ta.vwma(close, volume, length=20)', 5),
  (6, 'DEMA', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'تقاطع DEMA(8) فوق DEMA(21) = شراء، أسفل = بيع. أسرع من EMA بضعفين لكنه أكثر حساسية للضوضاء — استخدمه فقط في الأسواق الواضحة الاتجاه (ADX > 30).', 'ta.DEMA(close, 21)', 6),
  (7, 'TEMA', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'تقاطع TEMA(9) و TEMA(21) كإشارة دخول، مع تأكيد TEMA(55) كاتجاه أكبر. مثالي للسكالبينج السريع جدًا (1M, 5M) — أسرع متوسط بدون تأخر فعلي.', 'ta.TEMA(close, 21)', 7),
  (8, 'KAMA', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'السعر فوق KAMA الصاعد = شراء، تحت KAMA الهابط = بيع. الميزة: يتباطأ في الأسواق الجانبية ويتسارع في الترندات، لذا أقل إشارات كاذبة من EMA العادي.', 'ta.KAMA(close, 30)', 8),
  (9, 'ALMA', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'تغير ميل ALMA(21) لأعلى مع كسر السعر = شراء قوي. استخدم ALMA(9) للدخول، ALMA(50) للاتجاه — أنعم وأدق من EMA لكنه يحتاج تأكيد بحجم.', 'df.ta.alma(length=21, sigma=6.0)', 9),
  (10, 'McGinley Dynamic', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'السعر فوقه + الخط صاعد = شراء، تحته + هابط = بيع. الميزة الفريدة: لا يتأخر في الحركات السريعة ولا يعطي إشارات كاذبة في الجانبي — أفضل المتوسطات للسوق المتقلب.', 'Custom: McGinley Dynamic formula', 10),
  (11, 'Linear Regression', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'السعر داخل قناة الانحدار + ميل القناة صاعد = شراء عند الحد السفلي، ميل هابط = بيع عند العلوي. استخدم Linear Regression Slope لقياس قوة الترند رياضيًا.', 'ta.LINEARREG(close, 14)', 11),
  (12, 'Volatility Stop', 'مؤشرات الاتجاه', 'Trend', 'B', 0.0012048193, 'النقاط تحت السعر = اتجاه صاعد، فوقه = هابط. مثل Parabolic SAR لكن معتمد على ATR. الأقوى استخدامه كـ Trailing Stop بناءً على تذبذب السوق الفعلي.', 'Custom: ATR trailing stop', 12),
  (13, 'RSI - Relative Strength Index', 'مؤشرات الزخم', 'Momentum', 'S', 0.0024096386, 'تشبع بيعي < 30 + Bullish Divergence + توافق هيكلي = شراء قوي. تشبع شرائي > 70 + Bearish Divergence + كسر هيكلي = بيع قوي. لا تأخذ إشارة منفردة — انتظر الدايفرجنس دائمًا. خط 50 يفصل اتجاه الزخم.', 'ta.RSI(close, 14)', 13),
  (14, 'MACD - Moving Average Convergence Divergence', 'مؤشرات الزخم', 'Momentum', 'S', 0.0024096386, 'تقاطع خط MACD فوق الإشارة + هستوغرام أخضر فوق الصفر = شراء. تقاطع تحت + هستوغرام أحمر تحت الصفر = بيع. الأقوى: Hidden Divergence لتأكيد استمرار الترند، Regular Divergence للانعكاس.', 'ta.MACD(close, 12, 26, 9)', 14),
  (15, 'Stochastic Oscillator', 'مؤشرات الزخم', 'Momentum', 'A', 0.0018072289, 'تقاطع %K فوق %D في منطقة < 20 = شراء، تقاطع تحت %D في منطقة > 80 = بيع. إعدادات (14,3,3) للأطر الكبرى، (5,3,3) للسكالبينج. ابحث عن Hidden Divergence لتأكيد استمرار الترند.', 'ta.STOCH(high, low, close, 14, 3, 3)', 15),
  (16, 'Stochastic RSI', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'أسرع من Stochastic العادي. شراء عند خروج من < 20 وتقاطع لأعلى. بيع عند خروج من > 80 وتقاطع لأسفل. الأمثل للأطر الصغيرة جدًا (1M, 5M) في الذهب والنفط.', 'ta.STOCHRSI(close, 14, 5, 3)', 16),
  (17, 'ADX + DMI', 'مؤشرات الزخم', 'Momentum', 'S', 0.0024096386, 'ADX > 25 = ترند قوي. +DI فوق -DI = شراء، -DI فوق +DI = بيع. ADX < 20 = سوق جانبي تجنب التداول. ADX يحدد القوة، DI يحدد الاتجاه — بوصلة مزدوجة لا تخطئ.', 'ta.ADX + ta.PLUS_DI + ta.MINUS_DI (period=14)', 17),
  (18, 'CCI - Commodity Channel Index', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'فوق +100 = زخم شرائي قوي (شراء)، تحت -100 = زخم بيعي قوي (بيع). الأقوى في السلع والذهب. استخدم Zero Line Cross كتأكيد، والدايفرجنس للانعكاسات.', 'ta.CCI(high, low, close, 14)', 18),
  (19, 'Williams %R', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'قراءة < -80 + بدء صعود = شراء، > -20 + بدء هبوط = بيع. مشابه لـ Stochastic لكن أسرع. استخدمه كمؤشر تأكيد ثالث لـ RSI و Stochastic — لا يستخدم منفردًا.', 'ta.WILLR(high, low, close, 14)', 19),
  (20, 'ROC - Rate of Change', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'قراءة موجبة متزايدة = زخم صاعد قوي (شراء). سالبة متناقصة = زخم هابط قوي (بيع). تقاطع خط الصفر = تحول الزخم.', 'ta.ROC(close, 10)', 20),
  (21, 'Momentum', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'قراءة موجبة متزايدة = شراء، سالبة متناقصة = بيع. مماثل لـ ROC لكن بفرق مطلق. استخدم تقاطع الصفر كإشارة، والدايفرجنس مع السعر للانعكاس.', 'ta.MOM(close, 10)', 21),
  (22, 'Awesome Oscillator', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'تحول الهستوغرام من أحمر إلى أخضر فوق الصفر = شراء (Saucer). تحول من أخضر إلى أحمر تحت الصفر = بيع. الأقوى: Twin Peaks Pattern — قمتان فوق الصفر مع الثانية أقل = إشارة بيع كلاسيكية.', 'df.ta.ao()', 22),
  (23, 'Ultimate Oscillator', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'زخم متعدد الفترات (7, 14, 28). شراء: قاع أعلى + دايفرجنس صاعد + كسر آخر قمة. بيع: قمة أقل + دايفرجنس هابط + كسر آخر قاع.', 'ta.ULTOSC(high, low, close, 7, 14, 28)', 23),
  (24, 'TRIX', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'تقاطع فوق الصفر = شراء، تحت = بيع. مؤشر زخم على EMA ثلاثي يلغي الضوضاء قصيرة المدى. استخدمه كفلتر تأكيد للاتجاه فقط، لا للدخول.', 'ta.TRIX(close, 15)', 24),
  (25, 'Aroon Indicator + Aroon Oscillator', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'Aroon Up > 70 و Down < 30 = ترند صاعد قوي (شراء). العكس = ترند هابط (بيع). Aroon Oscillator > 0 = شراء، < 0 = بيع.', 'ta.AROON(high, low, 14) + ta.AROONOSC', 25),
  (26, 'Vortex Indicator (VI)', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, 'تقاطع +VI فوق -VI = شراء، تحت = بيع. مشابه لـ DMI لكن أكثر دقة في الأسواق المتذبذبة. استخدمه مع ADX — VI للاتجاه و ADX للقوة.', 'df.ta.vortex(length=14)', 26),
  (27, 'Coppock Curve', 'مؤشرات الزخم', 'Momentum', 'C', 0.0006024096, 'تقاطع فوق الصفر من قاع سالب = إشارة شراء استثمارية كلاسيكية. للأطر الأكبر فقط (4H+). الأقوى للسوينج تريدنج وليس السكالبينج.', 'Custom: WMA(ROC(11)+ROC(14), 10)', 27),
  (28, 'Chande Momentum Oscillator', 'مؤشرات الزخم', 'Momentum', 'B', 0.0012048193, '> +50 = ذروة شراء، < -50 = ذروة بيع. تقاطع الصفر = تحول زخم. الأفضل من RSI في الأسواق ذات التذبذب العالي (الذهب، النفط). استخدم الدايفرجنس للانعكاس.', 'ta.CMO(close, 14)', 28),
  (29, 'Bollinger Bands', 'مؤشرات التذبذب والتقلب', 'Volatility', 'S', 0.0024096386, 'لمسة الباند السفلي + شمعة انعكاسية = شراء، العلوي + شمعة انعكاسية = بيع. الذهبي: Bollinger Squeeze (تقارب الباندات) = انفجار قادم، الاتجاه يحدد بكسر الباند.', 'ta.BBANDS(close, 20, 2, 2)', 29),
  (30, 'ATR', 'مؤشرات التذبذب والتقلب', 'Volatility', 'A', 0.0018072289, 'ليس مؤشر اتجاه — يقيس التذبذب. استخدمه لتحديد SL (1.5 × ATR) و TP (3 × ATR). ارتفاع ATR مع كسر مستوى = حركة قوية متوقعة. ATR منخفض جدًا = انفجار قادم.', 'ta.ATR(high, low, close, 14)', 30),
  (31, 'Keltner Channels', 'مؤشرات التذبذب والتقلب', 'Volatility', 'B', 0.0012048193, 'كسر القناة العلوية = اختراق صاعد قوي (شراء). كسر السفلية = اختراق هابط قوي (بيع). أقوى من Bollinger في الترندات لاستخدامه ATR. الذهبي: Keltner داخل Bollinger = Squeeze حقيقي.', 'df.ta.kc(length=20, scalar=2.0)', 31),
  (32, 'FRAMA', 'مؤشرات التذبذب والتقلب', 'Volatility', 'B', 0.0012048193, 'ميل صاعد + السعر فوقه = شراء قوي، العكس = بيع. الميزة: يتباطأ في السوق المتذبذب (يقلل الإشارات الكاذبة) ويتسارع في الترند الواضح.', 'df.ta.frama(length=10)', 32),
  (33, 'Donchian Channels', 'مؤشرات التذبذب والتقلب', 'Volatility', 'B', 0.0012048193, 'كسر القناة العلوية (أعلى 20 شمعة) = شراء كلاسيكي (Turtle Trading). كسر السفلية = بيع. ادخل عند كسر 20-period، اخرج عند كسر 10-period المعاكس.', 'df.ta.donchian(20, 20)', 33),
  (34, 'Standard Deviation', 'مؤشرات التذبذب والتقلب', 'Volatility', 'B', 0.0012048193, 'ارتفاع SD مع كسر مستوى = حركة قوية محتملة. انخفاض SD = هدوء وبناء = تحضير لانفجار. ليس إشارة دخول — مؤشر تأكيد لقوة الحركة وحجم الـ SL/TP.', 'ta.STDDEV(close, 20, 1)', 34),
  (35, 'Historical Volatility', 'مؤشرات التذبذب والتقلب', 'Volatility', 'B', 0.0012048193, 'HV منخفض جدًا (في القاع المئوي 20%) = انفجار قادم بقوة. عند انخفاض HV لأدنى مستوى في 30 يوم، استعد لحركة كبيرة — اتجاه الكسر هو الإشارة.', 'Custom: rolling stdev of log returns × √252', 35),
  (36, 'Choppiness Index', 'مؤشرات التذبذب والتقلب', 'Volatility', 'A', 0.0018072289, '> 61.8 = سوق جانبي/متذبذب (تجنب التداول). < 38.2 = سوق ترند قوي. فلتر سياق ذهبي: لا تأخذ إشارات أي مؤشر آخر إلا إذا كان CI < 50.', 'df.ta.chop(length=14)', 36),
  (37, 'Chaikin Volatility', 'مؤشرات التذبذب والتقلب', 'Volatility', 'C', 0.0006024096, 'ارتفاع متسارع = توسع التذبذب (احتمال انعكاس وشيك). انخفاض = انكماش (هدوء قبل العاصفة). مؤشر تأكيد لقمم وقيعان السوق مع باندات Bollinger.', 'Custom: EMA(high-low,10) % change', 37),
  (38, 'Mass Index', 'مؤشرات التذبذب والتقلب', 'Volatility', 'C', 0.0006024096, 'ارتفاع المؤشر فوق 27 ثم نزوله تحت 26.5 = Reversal Bulge = إشارة انعكاس قوية. للأطر الأكبر فقط لاكتشاف الانعكاسات الكبرى.', 'df.ta.massi(fast=9, slow=25)', 38),
  (39, 'Volatility Index', 'مؤشرات التذبذب والتقلب', 'Volatility', 'C', 0.0006024096, 'ارتفاع شديد = خوف في السوق = انعكاس محتمل. هدوء طويل = رضى = انفجار وشيك. ليس إشارة دخول — يستخدم للسياق العام للسوق فقط.', 'Custom: ATR/close × 100 (VIX-like)', 39),
  (40, 'Volume (Normal)', 'مؤشرات الحجم والتدفق', 'Volume', 'A', 0.0018072289, 'ارتفاع السعر + ارتفاع الحجم = شراء حقيقي. ارتفاع السعر + انخفاض الحجم = شراء ضعيف (انعكاس محتمل). نزول السعر + ارتفاع الحجم = بيع قوي. القاعدة: لا حركة بدون حجم = حركة كاذبة.', 'Direct: volume column', 40),
  (41, 'OBV - On Balance Volume', 'مؤشرات الحجم والتدفق', 'Volume', 'A', 0.0018072289, 'OBV صاعد + السعر صاعد = ترند شراء حقيقي مدعوم. OBV هابط + السعر صاعد = Bearish Divergence = انعكاس وشيك. الأقوى لكشف تراكم/توزيع الأموال الذكية.', 'ta.OBV(close, volume)', 41),
  (42, 'MFI - Money Flow Index', 'مؤشرات الحجم والتدفق', 'Volume', 'A', 0.0018072289, 'مثل RSI لكن بالحجم. < 20 + بدء صعود = شراء قوي، > 80 + بدء نزول = بيع قوي. الأقوى من RSI في الأسواق ذات الحجم الحقيقي.', 'ta.MFI(high, low, close, volume, 14)', 42),
  (43, 'Accumulation / Distribution', 'مؤشرات الحجم والتدفق', 'Volume', 'B', 0.0012048193, 'A/D صاعد + السعر صاعد = تراكم حقيقي (شراء). A/D هابط + السعر صاعد = توزيع خفي (بيع وشيك). ابحث دائمًا عن الدايفرجنس بين A/D والسعر — أقوى إشارة انعكاس.', 'ta.AD(high, low, close, volume)', 43),
  (44, 'Chaikin Money Flow', 'مؤشرات الحجم والتدفق', 'Volume', 'B', 0.0012048193, '> +0.20 = ضغط شراء قوي مستمر، < -0.20 = ضغط بيع قوي. تقاطع الصفر = تحول الأموال. فلتر ذهبي: لا تأخذ شراء إذا كان CMF < 0، ولا بيع إذا كان > 0.', 'df.ta.cmf(length=20)', 44),
  (45, 'Chaikin Oscillator', 'مؤشرات الحجم والتدفق', 'Volume', 'B', 0.0012048193, 'تقاطع فوق الصفر مع ارتفاع السعر = شراء مدعوم. تقاطع تحت الصفر = بيع. الدايفرجنس بين Chaikin والسعر = الإشارة الذهبية للانعكاس.', 'ta.ADOSC(high, low, close, volume, 3, 10)', 45),
  (46, 'Klinger Oscillator', 'مؤشرات الحجم والتدفق', 'Volume', 'B', 0.0012048193, 'تقاطع خط Klinger فوق الإشارة في منطقة سالبة = شراء طويل المدى. تقاطع أسفل في منطقة موجبة = بيع. الأقوى للاتجاهات طويلة المدى.', 'df.ta.kvo(34, 55, 13)', 46),
  (47, 'Force Index', 'مؤشرات الحجم والتدفق', 'Volume', 'B', 0.0012048193, 'موجبة قوية متزايدة = ضغط شراء (شراء). سالبة متزايدة سلبًا = ضغط بيع. تقاطع الصفر = تحول قوة السوق. ادمجه مع EMA(13) لتنعيمه.', 'Custom: (close - close[1]) × volume; EMA(13) smooth', 47),
  (48, 'Ease of Movement', 'مؤشرات الحجم والتدفق', 'Volume', 'B', 0.0012048193, 'قراءات إيجابية كبيرة = السعر يصعد بسهولة (قوة شراء). سلبية كبيرة = ينزل بسهولة (قوة بيع). أداة فلتر ممتازة للترندات.', 'df.ta.eom(length=14)', 48),
  (49, 'Volume Oscillator', 'مؤشرات الحجم والتدفق', 'Volume', 'C', 0.0006024096, '> 0 = حجم متزايد (تأكيد للحركة الحالية)، < 0 = حجم متناقص (إنذار بضعف الحركة). ليس إشارة دخول — مؤشر تأكيد لحجم الترند.', 'Custom: EMA(vol,5) - EMA(vol,10) over EMA(vol,10)', 49),
  (50, 'Positive / Negative Volume Index', 'مؤشرات الحجم والتدفق', 'Volume', 'C', 0.0006024096, 'PVI أعلى من EMA(255) = السوق الذكي يشتري في أيام زيادة الحجم = شراء. NVI فوق EMA(255) = الأموال الذكية تشتري بهدوء = شراء قوي.', 'df.ta.pvi() and df.ta.nvi()', 50),
  (51, 'Negative Volume Index', 'مؤشرات الحجم والتدفق', 'Volume', 'C', 0.0006024096, 'NVI فوق EMA(255) = الأموال الذكية تشتري بهدوء في أيام انخفاض الحجم = شراء قوي. تحت = توزيع مؤسسي. الأقوى لكشف نشاط المؤسسات الصامت.', 'df.ta.nvi()', 51),
  (52, 'VWAP (الأساسي)', 'مؤشرات السلوك المؤسسي والأموال الذكية', 'SmartMoney', 'S', 0.0024096386, 'السعر فوق VWAP = المشترون يسيطرون. تحته = البائعون يسيطرون. المؤسسات تستخدم VWAP كمرجع تنفيذي — الارتداد من VWAP في اتجاه الترند = أفضل دخول إعادة. أهم مؤشر مؤسسي.', 'df.ta.vwap()', 52),
  (53, 'Anchored VWAP', 'مؤشرات السلوك المؤسسي والأموال الذكية', 'SmartMoney', 'A', 0.0018072289, 'VWAP مثبت من نقطة مهمة (قاع/قمة كبرى، حدث إخباري). السعر فوقه = القوة منذ تلك النقطة شرائية، تحته = بيعية. الأقوى لكشف نوايا المؤسسات.', 'Custom: VWAP from anchor point', 53),
  (54, 'Volume Profile (VPVR / VPSR)', 'مؤشرات السلوك المؤسسي والأموال الذكية', 'SmartMoney', 'S', 0.0024096386, 'POC = أعلى منطقة سيولة = ممغنطة للسعر. HVN = دعم/مقاومة قوي. LVN = مناطق حركة سريعة. ادخل من ارتداد POC في اتجاه الترند، استهدف HVN التالي.', 'Custom: volume bins by price (VPVR)', 54),
  (55, 'VWAP with Standard Deviation Bands', 'مؤشرات السلوك المؤسسي والأموال الذكية', 'SmartMoney', 'S', 0.0024096386, 'VWAP + 1σ و +2σ كمقاومات، -1σ و -2σ كدعوم. شراء عند ارتداد من -2σ مع شمعة انعكاسية، بيع عند ارتداد من +2σ. هذا VWAP المؤسسي الحقيقي.', 'Custom: VWAP ± 1σ, ±2σ', 55),
  (56, 'Volume Profile with POC / HVN / LVN', 'مؤشرات السلوك المؤسسي والأموال الذكية', 'SmartMoney', 'S', 0.0024096386, 'التحليل الأعمق لـ Volume Profile. ادخل عند رفض POC في اتجاه الترند الأكبر. كسر LVN = حركة سريعة. مزجها مع Order Flow = القوة المؤسسية الحقيقية.', 'Custom: VPVR + node detection (POC/HVN/LVN)', 56),
  (57, 'Market Profile (TPO)', 'مؤشرات السلوك المؤسسي والأموال الذكية', 'SmartMoney', 'S', 0.0024096386, 'Value Area (70% من النشاط) = منطقة القيمة العادلة. خروج السعر منها = حركة قوية في الاتجاه. أداة Wyckoff/AMT الحديثة. ادخل عند Value Area High/Low rejection.', 'Custom: TPO Market Profile', 57),
  (58, 'Cumulative Delta', 'مؤشرات السلوك المؤسسي والأموال الذكية', 'SmartMoney', 'S', 0.0024096386, 'Delta صاعد + السعر صاعد = شراء حقيقي مؤسسي. Delta هابط + السعر صاعد = Absorption (المؤسسات تبيع للقطيع) = إشارة انعكاس ذهبية. الأقوى لكشف Order Flow الحقيقي.', 'Custom: needs bid/ask volumes (Cumulative Delta)', 58),
  (59, 'Fibonacci Retracement', 'مؤشرات الدعم والمقاومة', 'SupportResistance', 'S', 0.0024096386, 'ارتداد من 0.382, 0.500, 0.618, 0.786 في اتجاه الترند الأكبر = إشارة دخول كلاسيكية. الأقوى: 0.618 + Order Block + شمعة انعكاسية = Golden Setup.', 'Custom: detect swing, draw 23.6/38.2/50/61.8/78.6', 59),
  (60, 'Pivot Points (Standard, Fibonacci, Camarilla, Woodie, DeMark)', 'مؤشرات الدعم والمقاومة', 'SupportResistance', 'S', 0.0024096386, 'ارتداد من PP, R1, S1 = إشارات يومية. كسر R1 = استهداف R2، كسر S1 = استهداف S2. Standard للسوق العادي، Camarilla للسكالبينج، Fibonacci للسوينج، DeMark للأطر الكبرى.', 'Custom: 5 pivot methods (Std/Fib/Camarilla/Woodie/DeMark)', 60),
  (61, 'Fibonacci Extension', 'مؤشرات الدعم والمقاومة', 'SupportResistance', 'A', 0.0018072289, 'استهداف 1.272, 1.414, 1.618, 2.618 لأخذ الأرباح بعد الترند. ارسم من قاع موجة 1 إلى قمة موجة 1، ثم إلى قاع موجة 2 — الـ 1.618 هو الهدف الأمثل لموجة 3.', 'Custom: project 1.272/1.414/1.618/2.618', 61),
  (62, 'Trend Lines', 'مؤشرات الدعم والمقاومة', 'SupportResistance', 'A', 0.0018072289, 'كسر خط ترند صاعد + ارتداد من الكسر (Retest) = بيع قوي. كسر خط ترند هابط + Retest = شراء. القاعدة: 3 لمسات = خط صحيح، 5+ = خط قوي جدًا.', 'Custom: detect swings, validate by 3+ touches', 62),
  (63, 'Fibonacci Fan', 'مؤشرات الدعم والمقاومة', 'SupportResistance', 'B', 0.0012048193, 'مراوح من نقطة محورية بنسب فيبو. ارتداد من خط 0.618 في اتجاه الترند = دخول قوي. الأقوى للأسواق ذات الزوايا الواضحة (الترندات المائلة).', 'Custom: fan from pivot at fib ratios', 63),
  (64, 'Fibonacci Arcs', 'مؤشرات الدعم والمقاومة', 'SupportResistance', 'C', 0.0006024096, 'أقواس فيبو لقياس الدعم/المقاومة الزمني والسعري معًا. الارتداد من القوس 0.618 = إشارة قوية. للأطر الكبيرة فقط (4H+).', 'Custom: arcs from pivot', 64),
  (65, 'Fibonacci Time Zones', 'مؤشرات الدعم والمقاومة', 'SupportResistance', 'C', 0.0006024096, 'خطوط زمنية عمودية بنسب فيبو من نقطة بداية. كل خط = منطقة احتمال تحول السعر. مفيد لتوقع توقيت الحركة وليس اتجاهها.', 'Custom: vertical lines at fib intervals', 65),
  (66, 'Fibonacci Speed Resistance Fan', 'مؤشرات الدعم والمقاومة', 'SupportResistance', 'C', 0.0006024096, 'مراوح بنسب 1/3 و 2/3 (أقل استخدامًا من فيبو العادي لكن قوية لأسواق Gann). ارتداد من 2/3 = إشارة قوية.', 'Custom: 1/3 and 2/3 fan', 66),
  (67, 'Ichimoku Cloud (Kinko Hyo)', 'مؤشرات الأنظمة المتكاملة', 'Integrated', 'S', 0.0024096386, 'السعر فوق السحابة + Tenkan فوق Kijun + Chikou فوق السعر السابق = شراء قوي مكتمل. السعر تحت + الترتيب العكسي = بيع قوي. أقوى نظام تحليل متكامل في العالم — يعطي 5 إشارات في مؤشر واحد.', 'df.ta.ichimoku(9, 26, 52)', 67),
  (68, 'Bollinger %B + Bandwidth', 'مؤشرات الأنظمة المتكاملة', 'Integrated', 'A', 0.0018072289, '%B > 1 = فوق العلوي (تشبع شرائي)، < 0 = تحت السفلي (تشبع بيعي). Bandwidth منخفض جدًا = انفجار قادم (Squeeze). الجمع: الاتجاه من Bandwidth، الإشارة من %B.', 'ta.BBANDS + custom %B and BW', 68),
  (69, 'McClellan Oscillator', 'مؤشرات الأنظمة المتكاملة', 'Integrated', 'C', 0.0006024096, 'مؤشر اتساع السوق (للأسهم). > +100 = ضغط شراء عام في السوق. < -100 = ضغط بيع. الأقوى للأسهم — يستخدم كفلتر سياق عام للسوق.', 'Custom: needs breadth data', 69),
  (70, 'Arms Index (TRIN)', 'مؤشرات الأنظمة المتكاملة', 'Integrated', 'C', 0.0006024096, '< 1 = ضغط شراء عام، > 1 = ضغط بيع. القراءة المتطرفة (< 0.5 أو > 2) = إشارة انعكاس وشيك.', 'Custom: needs breadth and volume', 70),
  (71, 'Advance / Decline Line', 'مؤشرات الأنظمة المتكاملة', 'Integrated', 'C', 0.0006024096, 'AD صاعد + السوق صاعد = صحة الترند، دايفرجنس = ضعف. للأسهم بشكل أساسي. في الفوركس: استخدمه على سلة عملات (DXY مع EUR/USD) لقراءة قوة الدولار.', 'Custom: needs A/D counts', 71);
